static void sleep_staging_predict(const float input[SLEEP_N_FEATURES], float output[SLEEP_N_CLASSES]) {
    float scores[SLEEP_N_CLASSES] = {0.0f};
    int node_offset = 0;
    int leaf_idx = 0;
    
    for (int t = 0; t < SLEEP_N_TREES; t++) {
        int n_nodes = sleep_tree_sizes[t];
        int base = node_offset;
        int bfs_idx = 0;
        
        while (bfs_idx < n_nodes) {
            int abs_idx = base + bfs_idx;
            if (sleep_features[abs_idx] == 255) {
                for (int c = 0; c < SLEEP_N_CLASSES; c++)
                    scores[c] += sleep_leaf_values[leaf_idx + c];
                leaf_idx += SLEEP_N_CLASSES;
                break;
            }
            if (input[sleep_features[abs_idx]] <= sleep_thresholds[abs_idx])
                bfs_idx = 2 * bfs_idx + 1;
            else
                bfs_idx = 2 * bfs_idx + 2;
        }
        node_offset += n_nodes;
    }
    
    /* Softmax */
    float max_s = scores[0];
    for (int i = 1; i < SLEEP_N_CLASSES; i++) if (scores[i] > max_s) max_s = scores[i];
    float sum = 0.0f;
    for (int i = 0; i < SLEEP_N_CLASSES; i++) { scores[i] = expf(scores[i] - max_s); sum += scores[i]; }
    for (int i = 0; i < SLEEP_N_CLASSES; i++) output[i] = scores[i] / sum;
}

